import{_ as e,a as i}from"./chunks/02.WVnmoTOm.js";import{_ as o,o as r,c as t,a2 as p}from"./chunks/framework.CqGPl1zp.js";const s="/newx-doc/img/%E6%8E%A5%E5%8F%A3%E6%96%87%E6%A1%A3/03.png",n="/newx-doc/img/%E6%8E%A5%E5%8F%A3%E6%96%87%E6%A1%A3/04.png",c="/newx-doc/img/%E6%8E%A5%E5%8F%A3%E6%96%87%E6%A1%A3/05.png",l="/newx-doc/img/%E6%8E%A5%E5%8F%A3%E6%96%87%E6%A1%A3/06.png",d="/newx-doc/img/%E6%8E%A5%E5%8F%A3%E6%96%87%E6%A1%A3/07.png",h="/newx-doc/img/%E6%8E%A5%E5%8F%A3%E6%96%87%E6%A1%A3/08.png",g="/newx-doc/img/%E6%8E%A5%E5%8F%A3%E6%96%87%E6%A1%A3/09.png",A="/newx-doc/img/%E6%8E%A5%E5%8F%A3%E6%96%87%E6%A1%A3/Apifox%E5%B8%B8%E8%A7%81%E9%97%AE%E9%A2%981.png",E="/newx-doc/img/%E6%8E%A5%E5%8F%A3%E6%96%87%E6%A1%A3/21.png",m="/newx-doc/img/%E6%8E%A5%E5%8F%A3%E6%96%87%E6%A1%A3/Knife4j%E8%B0%83%E7%94%A8.png",f="/newx-doc/img/%E6%8E%A5%E5%8F%A3%E6%96%87%E6%A1%A3/Swagger%E5%85%B3%E9%97%AD.png",I=JSON.parse('{"title":"接口文档","description":"","frontmatter":{},"headers":[],"relativePath":"api-doc.md","filePath":"api-doc.md","lastUpdated":null}'),k={name:"api-doc.md"};function u(_,a,x,b,w,P){return r(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="接口文档" tabindex="-1">接口文档 <a class="header-anchor" href="#接口文档" aria-label="Permalink to &quot;接口文档&quot;">​</a></h1><p>项目使用 Swagger 实现 RESTful API 的接口文档，提供两种解决方案：</p><p>*【推荐】 <a href="https://apifox.com/?utm_source=ydym" target="_blank" rel="noreferrer">Apifox</a> ：强大的 API 工具，支持 API 文档、API 调试、API Mock、API 自动化测试</p><ul><li>Knife4j：简易的 API 工具，仅支持 API 文档、API 调试</li></ul><p>为什么选择 Swagger 呢？</p><p>Swagger 通过 Java 注解实现 API 接口文档的编写。相比使用 Java 注释的方式，注解提供更加规范的接口定义方式，开发体验更好。</p><p>如果你没有学习 Swagger，可以阅读 <a href="https://www.iocoder.cn/Spring-Boot/Swagger/?yudao" target="_blank" rel="noreferrer">《芋道 Spring Boot API 接口文档 Swagger 入门 》</a> 文章。</p><h2 id="_1-apifox-使用" tabindex="-1">1. Apifox 使用 <a class="header-anchor" href="#_1-apifox-使用" aria-label="Permalink to &quot;1. Apifox 使用&quot;">​</a></h2><p>本小节，我们来将项目中的 API 接口，一键导入到 Apifox 中，并使用它发起一次 API 的调用。</p><h3 id="_1-1-下载工具" tabindex="-1">1.1 下载工具 <a class="header-anchor" href="#_1-1-下载工具" aria-label="Permalink to &quot;1.1 下载工具&quot;">​</a></h3><p>点击 <a href="https://apifox.com/?utm_source=ydym" target="_blank" rel="noreferrer">Apifox</a> 首页，下载对应的 Apifox 桌面版。如下图所示：</p><p>为什么要下载 Apifox 桌面版？</p><p>艿艿已经卸载 Postman，使用 Apifox 进行替代。国产软件，yyds 永远滴神！</p><p>国内很多互联网公司，包括百度、阿里、腾讯、字节跳动等等在内，都在使用 Apifox 作为 API 工具。</p><p><img src="'+e+'" alt="Apifox 下载"></p><p>解压后，双击进行安装即可。黑色界面，非常酷炫。</p><p><img src="'+i+'" alt="Apifox 界面"></p><h3 id="_1-2-api-导入" tabindex="-1">1.2 API 导入 <a class="header-anchor" href="#_1-2-api-导入" aria-label="Permalink to &quot;1.2 API 导入&quot;">​</a></h3><p>① 先点击「示例项目」，再点击「+」按钮，选择「导入」选项。</p><p><img src="'+s+'" alt="Apifox 界面 —— 导入"></p><p>② 先选择「URL 导入」按钮，填写 Swagger 数据 URL 为 <code>http://127.0.0.1:48081/v3/api-docs</code> 。如果失败，则可以尝试 <code>http://127.0.0.1:48080/v3/api-docs/all</code> 解决。</p><p><img src="'+n+'" alt="Apifox 界面 —— Swagger"></p><p>③ 先点击「提交」按钮，再点击「确认导入」按钮，完成 API 接口的导入。</p><p><img src="'+c+'" alt="Apifox 界面 —— Swagger"></p><p>④ 导入完成后，点击「接口管理」按钮，可以查看到 API 列表。</p><p><img src="'+l+'" alt="Apifox 界面 —— 接口管理"></p><h3 id="_1-3-api-调试" tabindex="-1">1.3 API 调试 <a class="header-anchor" href="#_1-3-api-调试" aria-label="Permalink to &quot;1.3 API 调试&quot;">​</a></h3><p>① 先点击右上角「请选择环境」，再点击「管理环境」选项，填写测试环境的地址为 <code>http://127.0.0.1:48080</code>，并进行保存。</p><p><img src="'+d+'" alt="Apifox 界面 —— 管理环境"></p><p>② 点击「管理后台 —— 认证」的「使用账号密码登录」接口，查看该 API 接口的定义。</p><p><img src="'+h+'" alt="Apifox 界面 —— 认证"></p><p>③ 点击「运行」按钮，填写 Headers 的 <code>tenant-id</code> 为 1，再点击 Body 的「自动生成」按钮，最后点击「发送」按钮。</p><p><img src="'+g+'" alt="Apifox 界面 —— 认证"></p><p>注意，登录接口不要填写 <code>socialType</code>、<code>socialCode</code>、<code>socialState</code> 这三个参数，它们是三方登录的参数。一定要去掉，不然会报错噢！</p><h3 id="_1-4-常见问题" tabindex="-1">1.4 常见问题 <a class="header-anchor" href="#_1-4-常见问题" aria-label="Permalink to &quot;1.4 常见问题&quot;">​</a></h3><p>问题 ①：分页 GET 请求时，如果有 <code>createTime</code> 这种时间类型的数组参数，会报错。如下图所示：</p><p><img src="'+A+'" alt="Apifox 常见问题 1"></p><p>答：把 <code>createTime</code> 左右两边的 <code>[]</code> 去掉，即可解决。</p><h2 id="_2-knife4j-使用" tabindex="-1">2. Knife4j 使用 <a class="header-anchor" href="#_2-knife4j-使用" aria-label="Permalink to &quot;2. Knife4j 使用&quot;">​</a></h2><h3 id="_2-1-如何使用" tabindex="-1">2.1 如何使用？ <a class="header-anchor" href="#_2-1-如何使用" aria-label="Permalink to &quot;2.1 如何使用？&quot;">​</a></h3><p>浏览器访问 <a href="http://127.0.0.1:48080/doc.html" target="_blank" rel="noreferrer">http://127.0.0.1:48080/doc.html</a> 地址，使用 Knife4j 查看 API 接口文档。</p><p><img src="'+E+'" alt="Knife4j 界面"></p><p>① 点击任意一个接口，进行接口的调用测试。这里，使用「管理后台 - 用户个中心」的“获得登录用户信息”举例子。</p><p>② 点击左侧「调试」按钮，并将请求头部的 <code>header-id</code> 和 <code>Authorization</code> 勾选上。</p><p>其中，<code>header-id</code> 为租户编号，<code>Authorization</code> 的 <code>&quot;Bearer test&quot;</code> 后面为用户编号（模拟哪个用户操作）。</p><p>如果不勾选，会出现 <code>&quot;请求的租户标识未传递，请进行排查&quot;</code> 或 <code>&quot;账号未登录&quot;</code> 错误。</p><p>③ 点击「发送」按钮，即可发起一次 API 的调用。</p><p><img src="'+m+`" alt="Knife4j 调试"></p><h3 id="_2-2-如何开启登录" tabindex="-1">2.2 如何开启登录？ <a class="header-anchor" href="#_2-2-如何开启登录" aria-label="Permalink to &quot;2.2 如何开启登录？&quot;">​</a></h3><p>生产环境下，建议 Knife4j 接口界面开启“安全认证”的功能，避免出现安全事故。</p><p>只需要在 <code>knife4j.basic</code> 配置项中，额外添加 Basic Auth 认证即可，如下所示：</p><div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">knife4j</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  basic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    username</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">admin</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Basic 认证用户名</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    password</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">admin</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Basic 认证密码</span></span></code></pre></div><h2 id="_3-swagger-技术组件" tabindex="-1">3. Swagger 技术组件 <a class="header-anchor" href="#_3-swagger-技术组件" aria-label="Permalink to &quot;3. Swagger 技术组件&quot;">​</a></h2><p>① 在 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-framework/yudao-spring-boot-starter-web/pom.xml" target="_blank" rel="noreferrer"><code>yudao-spring-boot-starter-web</code></a> 技术组件的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-framework/yudao-spring-boot-starter-web/src/main/java/cn/iocoder/yudao/framework/swagger/package-info.java" target="_blank" rel="noreferrer"><code>swagger</code></a> 包，实现了对 Swagger 的封装。</p><p>② 如果想要禁用 Swagger 功能，可通过 <code>springdoc.api-docs.enabled</code> 和 <code>knife4j.enable</code> 配置项为 <code>false</code>。一般情况下，建议 prod 生产环境进行禁用，避免发生安全问题。</p><p><img src="`+f+'" alt="Swagger 关闭"></p><p>友情提示：除了通过 enable 进行关闭外，更建议的是通过 knife4j 提供的 <code>knife4j.production = true</code> 来实现</p><ul><li>可见星球：<a href="https://wx.zsxq.com/group/88858522214142/topic/4844122558542458" target="_blank" rel="noreferrer">https://wx.zsxq.com/group/88858522214142/topic/4844122558542458</a></li><li>可见文档：<a href="https://doc.xiaominfo.com/docs/features/accessControl" target="_blank" rel="noreferrer">《Knife4j 文档 —— 访问权限控制》</a></li></ul><h2 id="_666-社区贡献相关" tabindex="-1">666. 社区贡献相关 <a class="header-anchor" href="#_666-社区贡献相关" aria-label="Permalink to &quot;666. 社区贡献相关&quot;">​</a></h2><ul><li><a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro/pulls/1380" target="_blank" rel="noreferrer">《pull request：新增通过注解的形式进行版本控制》</a></li></ul>',60)])])}const S=o(k,[["render",u]]);export{I as __pageData,S as default};
